import collections, bisect
def earliest_route(src,dst,tstart,maxgap,tend=None):
    # returns earliest arrival & path via temporal BFS
    ev=[e for e in events if e[2]>=tstart and (tend is None or e[2]<=tend)]
    reach={src:(tstart,None)}
    for u,v,t in ev:
        for a,b in ((u,v),(v,u)):
            if a in reach:
                ta=reach[a][0]
                # first hop: no gap constraint? use gap from tstart
                if t-ta<=maxgap and t>=ta:
                    if b not in reach or t<reach[b][0]:
                        reach[b]=(t,(a,t))
    return reach
