    for u,v,t in events:
        if t<tstart or t>tmax: continue
        if u in reach and t-reach[u]<=maxgap:
            if v not in reach or t<reach[v]:
                reach[v]=t; prev[v]=(u,t)
        if v in reach and t-reach[v]<=maxgap:
            if u not in reach or t<reach[u]:
                reach[u]=t; prev[u]=(v,t)
    return reach,prev

