def route(src,dst,tstart,maxgap,tmax):
    reach={src:None}; prev={}
    for u,v,t in events:
        if t<tstart or t>tmax: continue
        for a,b in ((u,v),(v,u)):
            if a in reach:
                ta=reach[a]
                if ta is not None and t-ta>maxgap: continue
                if b not in reach: reach[b]=t; prev[b]=(a,t)
    if dst not in reach: return None
    path=[];cur=dst
    while cur in prev: path.append((prev[cur][0],cur,prev[cur][1])); cur=prev[cur][0]
    return list(reversed(path))
